package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.person.Holds;
import net.officefloor.hq.app.person.InvalidPersonException;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.person.PersonResponse;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.DatedAmount;
import net.officefloor.hq.app.setting.SettingHistory;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Take the person's statement: record their due-total now (late charges included, at most the sheet's cap) and the sheet's today, bind
 *  each of their claims that counts to its due as shown now (late charge and floor included: while bound it no longer
 *  follows the sheet's today; one already bound is bound again to the figure it shows), and unbind the rest (their due is live again; a claim deferred on today is left unbound). A settled claim's
 *  fixed due is left as it is.
 *  <p>Taken as of a date (on or before the sheet's today; refused after it, or for a person added after it), the
 *  same is done with the sheet as it stood at the end of that date: every change made while the sheet's today was on
 *  or before it counts, every later one does not, and the date stands in for the sheet's today. Their claims that
 *  counted then are bound to their dues as shown then, the rest are unbound, and the date is recorded as the statement's. */
public class SaveStatement {
    public void save(@Val StatementRequest request, @Val Person loaded, PersonRepository people,
            ClaimRepository claims, RateRepository rates, SheetRepository sheets, SettingRepository settings,
            Out<Statement> statement, Out<PersonResponse> saved) throws InvalidPersonException {
        people.lock(loaded);
        Person person = people.find(loaded.sheetId(), loaded.id());
        String sheetId = person.sheetId();
        LocalDate today = sheets.today(sheetId);
        LocalDate asOf = request.asOf() != null ? LocalDate.parse(request.asOf()) : null;
        if (asOf != null && today != null && asOf.isAfter(today)) {
            throw new InvalidPersonException("A statement cannot be taken as of a date after the sheet's today ("
                    + today + ").");
        }
        if (asOf != null && !people.addedBy(person, asOf)) {
            throw new InvalidPersonException(person.name() + " was not on the sheet on " + asOf + ".");
        }
        LocalDate on = asOf != null ? asOf : today;
        List<Claim> theirs = claims.listForPerson(sheetId, person.id());
        Rounding now = Rounding.of(sheetId, settings, sheets, claims);

        List<Claim> then;
        Grades grades;
        Holds holds;
        LocalDate retiredFrom;
        Rates ratesThen;
        DatedAmount floor;
        LateCharge late;
        BigDecimal cap;
        if (asOf == null) {
            then = theirs;
            grades = person.grades();
            holds = person.holds();
            retiredFrom = person.retiredFrom();
            ratesThen = rates;
            floor = settings.floor(sheetId);
            late = LateCharge.of(sheetId, settings, sheets, claims, people);
            cap = settings.cap(sheetId);
        } else {
            then = claims.listForPersonAsOf(sheetId, person.id(), asOf);
            grades = people.gradesAsOf(person, asOf);
            holds = people.holdsAsOf(person, asOf);
            retiredFrom = people.retiredFromAsOf(person, asOf);
            ratesThen = rates.asOf(sheetId, asOf);
            SettingHistory history = settings.historyAsOf(sheetId, asOf);
            floor = history::floorOn;
            LocalDate policy = settings.policyDate(sheetId);
            late = new LateCharge(history::latePctOn, asOf, new Rounding(policy != null ? policy : asOf,
                    now.numbered(), history.of(SettingHistory.ROUNDING)), LateCharge.Grace.of(history, Map.of(person.id(), grades)));
            cap = history.capOn(asOf);
        }

        BigDecimal total = Dues.capped(Dues.total(sheetId, then, grades, holds, retiredFrom, on, ratesThen, floor,
                late), cap);
        Map<Long, BigDecimal> bound = new HashMap<>();
        for (Claim c : then) {
            if (Dues.counts(c, holds, retiredFrom, on)) {
                bound.put(c.id(), Dues.shown(c, grades, ratesThen, floor, late));
            }
        }
        for (Claim c : theirs) {
            if (bound.containsKey(c.id())) {
                claims.state(c, true, bound.get(c.id()));
            } else if (c.stated()) {
                claims.state(c, false, null);
            }
        }
        people.stated(person, total, on);
        statement.set(new Statement(sheetId, person.name(), total, bound.size(), asOf));
        saved.set(PersonResponse.from(people.find(sheetId, person.id())));
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimStatus;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.person.Holds;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.setting.DatedAmount;

/** Claim figures and due-totals, as the screen shows them. */
public final class Dues {
    private Dues() {
    }

    /** A claim's figure: the due fixed when it was settled, else the one its last statement bound it to, n/a
     *  included (an OPEN or PENDING one alike), else live: its amount times its person's rate in force on
     *  its date for their grade then, divided by 100, rounded to two decimals as the claim rounds (see Rounding); null
     *  (n/a) when no rate applies. The floor is not in it: it is applied last (see shown). */
    public static BigDecimal figure(Claim claim, Grades grades, Rates rates, Rounding rounding) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated()) {
            return claim.statedDue();
        }
        return live(claim, grades, rates, rounding);
    }

    /** A claim's due as its row shows it: the due fixed when it was settled, else the one its last statement bound
     *  it to as shown then (late charge and floor included; n/a included), else the greater of the floor in force on
     *  its date and its live figure with the late charge on it added (a correction, a negative amount, has no floor
     *  and no charge); null (n/a) when it has no figure. */
    public static BigDecimal shown(Claim claim, Grades grades, Rates rates, DatedAmount floor,
            LateCharge late) {
        if (claim.settledDue() != null) {
            return claim.settledDue();
        }
        if (claim.stated()) {
            return claim.statedDue();
        }
        BigDecimal figure = figure(claim, grades, rates, late.rounding());
        if (figure == null || claim.amount().signum() < 0) {
            return figure;
        }
        return figure.add(late.on(claim, figure)).max(floor.on(claim.date()));
    }

    /** A claim's live figure: its amount times its person's rate in force on its date for their grade then (of the
     *  rates that reach it: a forward-only rate only reaches claims added after it), divided by 100, rounded to two
     *  decimals as the claim rounds (see Rounding); null (n/a) when no rate applies. */
    public static BigDecimal live(Claim claim, Grades grades, Rates rates, Rounding rounding) {
        return rates.on(claim.sheetId(), grades.on(claim.date()), claim.date(), claim.id())
                .map(r -> claim.amount().multiply(r.pct()).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)))
                .orElse(null);
    }

    /** Whether a claim counts toward its person's figures and every live total: an OPEN, PENDING or SETTLED one,
     *  except an OPEN one held itself or dated within one of its person's holds and not bound by a statement, an OPEN or PENDING one
     *  not bound by a statement once its person's retirement date is reached (see retiredOut), and one deferred on the
     *  sheet's today (see Claim.deferredOn). */
    public static boolean counts(Claim claim, Holds holds, LocalDate retiredFrom, LocalDate today) {
        return claim.status().counts() && !claim.deferredOn(today)
                && !(claim.status() == ClaimStatus.OPEN && !claim.stated() && (claim.held() || holds.covers(claim.date())))
                && !retiredOut(claim, retiredFrom, today);
    }

    /** Whether a claim counts toward claimed and the claimed-total: as it counts (see counts), except a hold (the
     *  claim's own or its person's) does not take it out — only its due leaves the totals while held. */
    public static boolean countsClaimed(Claim claim, LocalDate retiredFrom, LocalDate today) {
        return claim.status().counts() && !claim.deferredOn(today) && !retiredOut(claim, retiredFrom, today);
    }

    /** Whether a claim leaves the live totals because its person is retired: the sheet's today is on or after their
     *  retirement date (null: not retired) and it is OPEN or PENDING and not bound by a statement. */
    private static boolean retiredOut(Claim claim, LocalDate retiredFrom, LocalDate today) {
        return retiredFrom != null && today != null && !today.isBefore(retiredFrom) && !claim.stated()
                && (claim.status() == ClaimStatus.OPEN || claim.status() == ClaimStatus.PENDING);
    }

    /** Whether a claim counts toward a period's due-totals: its status at the end of the period's last day (see
     *  ClaimLogRepository.statusesAt; null: it was added after) is OPEN, PENDING or SETTLED, and it is left out
     *  as the live rules leave it out: deferred on the sheet's today, or an OPEN one dated within one of its
     *  person's holds and not bound by a statement, or an OPEN or PENDING one of a retired person (see counts). */
    public static boolean countsAtEnd(Claim claim, ClaimStatus atEnd, Holds holds, LocalDate retiredFrom,
            LocalDate today) {
        return atEnd != null && atEnd.counts() && !claim.deferredOn(today)
                && !(claim.status() == ClaimStatus.OPEN && !claim.stated() && (claim.held() || holds.covers(claim.date())))
                && !retiredOut(claim, retiredFrom, today);
    }

    /** A person's due-total: the dues (as shown) of their claims that count added up, skipping n/a; null (n/a) when
     *  their grade today has no rate today, unless a claim that counts has a figure (settled, stated, or live at
     *  the grade in force on its date). */
    public static BigDecimal total(String sheetId, List<Claim> claims, Grades grades, Holds holds,
            LocalDate retiredFrom, LocalDate today, Rates rates, DatedAmount floor, LateCharge late) {
        List<Claim> counted = claims.stream().filter(c -> counts(c, holds, retiredFrom, today)).toList();
        List<BigDecimal> figures = counted.stream().map(c -> shown(c, grades, rates, floor, late))
                .filter(f -> f != null).toList();
        if (figures.isEmpty() && rates.on(sheetId, grades.on(today), today).isEmpty()) {
            return null;
        }
        return figures.stream().reduce(new BigDecimal("0.00"), BigDecimal::add);
    }

    /** A due-total at most the sheet's cap (null: none); n/a (null) is not capped. */
    public static BigDecimal capped(BigDecimal total, BigDecimal cap) {
        return total != null && cap != null ? total.min(cap) : total;
    }
}
package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Grades;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.setting.DatedAmount;
import net.officefloor.hq.app.setting.SettingHistory;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;

/** The sheet's late charge as it is today: its late percent by date (a claim gains the one in force on each 30-day boundary past its due-by plus its grace; a claim is overdue past its own due-by, fixed when
 *  it was created, plus its grace) and its today (null: none, so nothing is overdue) and each claim's grace (days: the
 *  grace in force on its date of its person's grade in force on that date; 0 when none). */
public record LateCharge(DatedAmount pct, LocalDate today, Rounding rounding, Grace grace) {

    /** A claim's grace, in days. */
    @FunctionalInterface
    public interface Grace {
        int of(Claim claim);

        /** No grace for any claim. */
        Grace NONE = claim -> 0;

        /** The grace of the grade in force on a claim's date (its person's, by id, in `grades`) in force on that date,
         *  in the history. */
        static Grace of(SettingHistory history, Map<Long, Grades> grades) {
            return claim -> history.graceFor(grades.getOrDefault(claim.personId(), Grades.NONE).on(claim.date()),
                    claim.date());
        }
    }

    /** The sheet's late charge as it is now. */
    public static LateCharge of(String sheetId, SettingRepository settings, SheetRepository sheets,
            ClaimRepository claims, PersonRepository people) {
        Map<Long, Grades> grades = people.list(sheetId).stream()
                .collect(Collectors.toMap(Person::id, Person::grades, (a, b) -> a));
        return new LateCharge(settings.latePct(sheetId), sheets.today(sheetId),
                Rounding.of(sheetId, settings, sheets, claims), Grace.of(settings.history(sheetId), grades));
    }

    /** No late charge at all. */
    public static LateCharge none() {
        return new LateCharge(DatedAmount.always(BigDecimal.ZERO), null, Rounding.none(), Grace.NONE);
    }

    /** The day a claim's late charge counts from: its due-by plus its grace. */
    public LocalDate lateFrom(Claim claim) {
        return claim.dueBy().plusDays(grace.of(claim));
    }

    /** Whether a claim is overdue: it is OPEN or PENDING, not deferred on today, and its due-by plus its grace is
     *  before today. */
    public boolean overdue(Claim claim) {
        return claim.status().unsettled() && today != null && !claim.deferredOn(today)
                && lateFrom(claim).isBefore(today);
    }

    /** The charge on a claim whose figure is `figure`: for each full 30 days it is overdue, the late percent in force
     *  on that boundary date (its due-by plus its grace plus 30, 60, 90 ... days) of the figure plus the charges of the boundaries before it (compounding), each
     *  rounded to two decimals as the claim rounds (see Rounding), the charges added up (a boundary whose percent is 0.00 adds nothing); 0.00 when it is not
     *  overdue, or it is a correction (a negative amount), or its late charge was waived. */
    public BigDecimal on(Claim claim, BigDecimal figure) {
        BigDecimal total = new BigDecimal("0.00");
        if (!overdue(claim) || claim.amount().signum() < 0 || claim.waived()) {
            return total;
        }
        LocalDate from = lateFrom(claim);
        long periods = ChronoUnit.DAYS.between(from, today) / 30;
        for (long n = 1; n <= periods; n++) {
            BigDecimal pct = this.pct.on(from.plusDays(30 * n));
            if (pct.signum() != 0) {
                total = total.add(figure.add(total).multiply(pct).divide(BigDecimal.valueOf(100), 2, rounding.of(claim)));
            }
        }
        return total;
    }
}
    private void kept(String sheetId, long id) {
        jdbc.update("INSERT INTO claim_history (sheet_id, claim_id, person_id, amount, claim_date, note, status, "
                + "claim_number, settled_due, opened_by, stated, stated_due, corrects, due_from, terms_days, deferred_until, proofs, "
                + "split_from, late_entry, reminded_on, ref, tags, due_by, made_on, waived, proof_photos, held) SELECT c.sheet_id, c.id, c.person_id, c.amount, c.claim_date, c.note, "
                + "c.status, c.claim_number, c.settled_due, c.opened_by, c.stated, c.stated_due, c.corrects, c.due_from, c.terms_days, "
                + "c.deferred_until, c.proofs, c.split_from, c.late_entry, c.reminded_on, c.ref, c.tags, c.due_by, s.today, c.waived, c.proof_photos, c.held FROM claim c JOIN sheet s ON s.id = "
                + "c.sheet_id WHERE c.sheet_id = ? AND c.id = ?", sheetId, id);
    }

    /** Keep the claim in its history when the change went through; whether it did. */
    private boolean kept(Claim claim, boolean changed) {
        if (changed) {
            kept(claim.sheetId(), claim.id());
        }
        return changed;
    }

    /** The sheet's claims as they stood at the end of the day: each claim's last kept state made while the sheet's
     *  today was on or before it (one kept before history was, at any day), newest first; a claim added after then is
     *  not among them. */
    public List<Claim> listAsOf(String sheetId, LocalDate end) {
        return jdbc.query("SELECT h.claim_id AS id, h.* FROM claim_history h WHERE h.sheet_id = ? AND h.id = ("
                + "SELECT MAX(l.id) FROM claim_history l WHERE l.sheet_id = h.sheet_id AND l.claim_id = h.claim_id "
                + "AND (l.made_on IS NULL OR l.made_on <= ?)) ORDER BY h.claim_id DESC", row(sheetId), sheetId, end);
    }

    /** The person's claims as they stood at the end of the day: each claim's last kept state made while the sheet's
     *  today was on or before it (one kept before history was, at any day), newest first; a claim added after then,
     *  or that was another person's then, is not among them. */
    public List<Claim> listForPersonAsOf(String sheetId, long personId, LocalDate end) {
        return jdbc.query("SELECT h.claim_id AS id, h.* FROM claim_history h WHERE h.sheet_id = ? AND h.id = ("
                + "SELECT MAX(l.id) FROM claim_history l WHERE l.sheet_id = h.sheet_id AND l.claim_id = h.claim_id "
                + "AND (l.made_on IS NULL OR l.made_on <= ?)) AND h.person_id = ? ORDER BY h.claim_id DESC",
                row(sheetId), sheetId, end, personId);
    }
}

